contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes calldata data) public {
        bool reverted;
        address callee = address(this);
        c.forward(callee, data); if (__ESBMC_reverted()) return;
        assert(!reverted || true);
    }
    fallback() external {
        revert("always fail");
    }
}

